<template>
	<view class="zuti">
		<!-- #ifndef H5 -->
		<cu-custom :bgImage="imgurl + 'indexbgc.png'" :isContent="true" :isBack="true" :backColor="'text-white'">
			<block slot="content">
				<text class="text-xl text-bold text-white">AI测试</text>
			</block>
		</cu-custom>
		<!-- #endif -->

		<view class="list">
			<view class="list-item" v-for="item in news" :key="item.id" @click="to(`/pages/index/newsDetail?id=${item.id}`)">
				<view class="list-item-img">
					<image src="../../static/images/img2.png" mode="aspectFill"></image>
				</view>
				<view class="list-item-tex">
					<view class="list-item-tit ovHide2">晚上睡觉前喝水，危害比吃夜宵还大?</view>
					<view class="list-item-cont">
						<view class="name">2024.08.13</view>
					</view>
				</view>
			</view>
		</view>

		<!-- 		加载提示 -->
		<view class="loading" v-if="showLoading">
			<text style="--i:1">加</text>
			<text style="--i:2">载</text>
			<text style="--i:3">中</text>
			<text style="--i:4">.</text>
			<text style="--i:5">.</text>
			<text style="--i:6">.</text>
		</view>
		<view class="end" v-if="showNone">暂无更多...</view>

		<!--  底部   -->
		<tabBar :tabCur="1" />
	</view>
</template>
<script>
	import {
		loaded,
		loading,
		toast,
		redirectTo,
		navigateTo
	} from '@/utils/index.js';
	import {
		img_PATH
	} from '@/config';
	import tabBar from '@/components/tabbar.vue';
	export default {
		data() {
			return {
				imgurl: img_PATH,
				CustomBar: this.CustomBar,
				showLoading: false,
				showNone: false,
			};
		},
		computed: {
			style() {
				return `background-image:url(${this.imgurl}indexbgc.png);background-position-y: ${- this.CustomBar}px;`
			},
			paddingbottom() {
				const res = wx.getSystemInfoSync()
				const {
					screenHeight,
					safeArea: {
						bottom
					}
				} = res
				if (screenHeight && bottom) {
					let safeBottom = screenHeight - bottom
					return safeBottom
				} else {
					return 0
				}
			}
		},
		components: {
			tabBar
		},
		onLoad() {

		},
		created() {

		},
		// 触底的事件
		onReachBottom() {

		},
		methods: {
			async list() {
				this.showNone = false
				this.showLoading = true
				let _data = await getNews(this.search.page, this.search.limit);
				if (_data.status === 200) {
					if (_data.rows.length === 0) {
						this.showLoading = false
						this.showNone = true
						return
					}
					this.search.page++
					this.showLoading = false
					this.news = [...this.news, ..._data.rows]
				}
			},
			to(path) {
				navigateTo(path)
			},
		},

	}
</script>

<style scoped lang="scss">
	.zuti {
		min-height: 100vh;
		width: 100%;
		background-size: 100% auto;
		background-attachment: fixed;
		background-repeat: no-repeat;
		background-color: #f8f3f3;

	}
</style>